import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate, conversion_rate_by_group, conversions_in_window,
    longest_conversion_streak, pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_last_duplicate_wins_even_if_its_day_is_earlier():
    old = {"id": "a", "day": 9}
    new = {"id": "a", "day": 2}
    b = {"id": "b", "day": 2}
    z = {"id": "z", "day": 1}
    assert dedupe_sessions([old, b, z, new]) == [z, new, b]


def test_parse_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", " \t", "  # header", " a , 1 , 0 ", " b , 3 ,  "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["missing,field", "too,many,1,0", "a,not-a-day,1"])
def test_parse_errors_use_original_line_number(bad):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["a,1,0", "# skipped", "", bad])


def test_calendar_counts_and_trailing_windows():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    counts = daily_conversion_counts(events, 1, 4)
    assert counts == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []
    assert conversions_in_window(counts, 2) == 0
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 5) == 2


def test_summary_weights_sessions_and_uses_calendar_days():
    groups = {"a": parse_session_log(["x,1,1", "y,4,0"]),
              "b": parse_session_log(["z,1,1"]), "empty": []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_order_and_empty_groups():
    groups = {"z": [{"converted": False}], "empty": [], "b": [{"converted": True}],
              "a": [{"converted": True}]}
    assert top_converting_groups(groups, 10) == ["a", "b", "z"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 1.0), ("empty", None), ("z", 0.0),
    ]


def test_only_consecutive_positive_days_extend_streak():
    assert longest_conversion_streak([3, 0, 1, 2, -1, 3]) == 2
    assert longest_conversion_streak([]) == 0
